import{_ as i,o as s,c as a,a2 as t}from"./chunks/framework.DncwoWA8.js";const k=JSON.parse('{"title":"Install skills and maintain instructions separately","description":"","frontmatter":{},"headers":[],"relativePath":"guide/install.md","filePath":"guide/install.md"}'),n={name:"guide/install.md"};function l(o,e,r,c,d,p){return s(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="install-skills-and-maintain-instructions-separately" tabindex="-1">Install skills and maintain instructions separately <a class="header-anchor" href="#install-skills-and-maintain-instructions-separately" aria-label="Permalink to &quot;Install skills and maintain instructions separately&quot;">​</a></h1><p>Use the Node.js CLI to install skills. Use <code>sync-my-agents</code> only when you explicitly want instruction-document changes. Neither operation requires or automatically launches the other.</p><h2 id="run-the-node-js-cli" tabindex="-1">Run the Node.js CLI <a class="header-anchor" href="#run-the-node-js-cli" aria-label="Permalink to &quot;Run the Node.js CLI&quot;">​</a></h2><p>You need Node.js 24, npm/npx, Git, and a trusted destination project. Read that project&#39;s instructions and follow its branch/workspace rules before approving writes. GitHub-based <code>npx</code> downloads the executable and its declared runtime dependencies into npm&#39;s cache; it does not publish an npm package.</p><p>Replace <code>&lt;tag-or-commit&gt;</code> with a reviewed GitHub ref that contains the new CLI. Unpublished local changes are not available through GitHub.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">npx</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -y</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> github:dragoscirjan/ai#</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">&lt;</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;">tag-or-commi</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">t</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">&gt;</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> --help</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">npx</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -y</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> github:dragoscirjan/ai#</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">&lt;</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;">tag-or-commi</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">t</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">&gt;</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> list</span></span></code></pre></div><p>The root package&#39;s single <code>bin</code> entry invokes <code>scripts/skills/sync.mjs</code>. It reads <code>catalog/skill-catalog.yaml</code>; it is not a skill or a personal agent command. A checkout with approved runtime dependencies can run <code>node scripts/skills/sync.mjs</code> with the same arguments.</p><h2 id="preview-a-selection" tabindex="-1">Preview a selection <a class="header-anchor" href="#preview-a-selection" aria-label="Permalink to &quot;Preview a selection&quot;">​</a></h2><p>From the destination project&#39;s root, preview an explicit selection:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">npx</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -y</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> github:dragoscirjan/ai#</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">&lt;</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;">tag-or-commi</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">t</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">&gt;</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> --skill</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> coding-with-rules</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> --agent</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> pi</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> --target</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> .</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> --dry-run</span></span></code></pre></div><p>The preview lists <code>coding</code> before <code>coding-with-rules</code>, because it is a required skill. It shows exact installation argument arrays, destinations, legal-file changes, filtering, and any blockers. A preview performs no source downloads or target writes after the executable itself has been acquired.</p><p>Use <code>--category coding</code> instead of <code>--skill</code> to review that category&#39;s project-scoped members. Repeat <code>--category</code>, <code>--skill</code>, or <code>--agent</code>, or provide comma-separated values. Supported agents are <code>pi</code>, <code>opencode</code>, and <code>claude-code</code>. In an interactive terminal, choose categories, then individual skills within each selected category, then agents. Each category&#39;s skill checklist starts with all eligible skills checked. Use the arrow keys to move, Space to toggle one choice, A to select or clear all, and Enter to accept. You can clear a category completely to skip it. Clearing every category cancels without installing anything. Category and agent selection still require at least one choice.</p><p>Required prerequisites cannot be omitted while keeping a skill that needs them. The preview identifies any required skills added back, even if you unchecked them. Explicit <code>--skill</code> selections are also retained. Deselecting an installed skill never removes it.</p><p><code>--yes</code>, <code>--json</code>, and noninteractive category runs bypass these skill checklists and retain the existing all-members behavior. Use explicit <code>--skill</code> flags for exact scripted subsets. The final confirmation defaults to no; Ctrl+C cancels a prompt cleanly with exit code 130, before installation. Noninteractive runs must provide their selections explicitly.</p><p>Use <code>--ref &lt;ref&gt;</code> to choose this repository&#39;s skill-source revision separately from the CLI revision. Without it, authored skill commands follow the catalog&#39;s configured ref. Upstream sources retain their catalogued immutable pins. Pinning the CLI alone does not pin a mutable authored-skill ref.</p><h2 id="copy-skills-into-a-plugin-or-custom-directory" tabindex="-1">Copy skills into a plugin or custom directory <a class="header-anchor" href="#copy-skills-into-a-plugin-or-custom-directory" aria-label="Permalink to &quot;Copy skills into a plugin or custom directory&quot;">​</a></h2><p>Use <code>--skills-dir</code> when you want portable skill folders in an exact directory rather than normal agent installations. The owning project directory must already exist. For an existing Claude plugin, replace <code>my-plugin</code> with its root:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">npx</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -y</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> github:dragoscirjan/ai#</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">&lt;</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;">tag-or-commi</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">t</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">&gt;</span><span style="--shiki-light:#EA76CB;--shiki-dark:#F5C2E7;"> \\</span></span>
<span class="line"><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;">  --target</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> ./my-plugin</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> --skills-dir</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> skills</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> --skill</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> coding-with-rules</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> --agent</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> claude-code</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> --dry-run</span></span></code></pre></div><p>The preview targets this layout and includes the required <code>coding</code> skill:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>my-plugin/</span></span>
<span class="line"><span>├── .claude-plugin/</span></span>
<span class="line"><span>│   └── plugin.json                 unchanged, if present</span></span>
<span class="line"><span>└── skills/</span></span>
<span class="line"><span>    ├── coding/</span></span>
<span class="line"><span>    │   ├── SKILL.md</span></span>
<span class="line"><span>    │   └── LICENSE</span></span>
<span class="line"><span>    └── coding-with-rules/</span></span>
<span class="line"><span>        ├── SKILL.md</span></span>
<span class="line"><span>        ├── references/</span></span>
<span class="line"><span>        └── LICENSE</span></span></code></pre></div><p>This matches <a href="https://code.claude.com/docs/en/plugins/components" target="_blank" rel="noreferrer">Claude&#39;s documented plugin skill layout</a>. Do not put skills under <code>.claude-plugin/</code>; that directory contains plugin metadata. For another custom directory, choose its exact path and configure its consumer separately. This script never edits plugin manifests, loads or registers plugins, changes trust, or executes installed helpers.</p><p>Relative <code>--skills-dir</code> paths resolve under <code>--target</code>, not the invocation directory. An absolute path must also be a subdirectory of <code>--target</code>. Paths outside that project, its root itself, Git metadata, symlink traversal, and overlaps with protected instruction documents are rejected. Point <code>--target</code> at the owning project rather than bypassing its scope. A missing output directory is created only after confirmation and successful source verification.</p><p>Keep <code>--agent claude-code</code> to check the selected skills&#39; catalogued Claude compatibility. In this mode, agent selection does not create harness-specific directories. Even personal catalog entries explicitly selected with <code>--scope personal</code> are copied only into this output directory, never installed globally.</p><p>Review the dry run, then repeat without <code>--dry-run</code> to confirm or use <code>--yes</code> for a separately approved noninteractive run. All selected sources and legal files are acquired in a disposable workspace and verified before any output skill folder changes. Acquisition follows the selected harness&#39;s native layout, including Claude&#39;s <code>.claude/skills</code>; only verified flat skill folders are published. Installation records stay in that temporary workspace; the plugin receives no normal <code>.agents</code>/<code>.claude</code> directories, new manager locks, or CLI lock changes.</p><p>Unselected folders and project/plugin metadata remain unchanged. Existing selected folders require <code>--overwrite</code>; that approval replaces the complete selected folder, including obsolete files. Replacement is per skill, not an all-or-nothing transaction for the entire selection. A failed replacement restores the original when possible. If an unexpected concurrent write prevents restoration, the error identifies a preserved backup for inspection; do not delete that backup blindly.</p><h2 id="confirm-and-verify" tabindex="-1">Confirm and verify <a class="header-anchor" href="#confirm-and-verify" aria-label="Permalink to &quot;Confirm and verify&quot;">​</a></h2><p>Review the preview. Repeat the command without <code>--dry-run</code> to receive an interactive confirmation. For an already approved noninteractive run, add <code>--yes</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">npx</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -y</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> github:dragoscirjan/ai#</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">&lt;</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;">tag-or-commi</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">t</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">&gt;</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> --skill</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> coding-with-rules</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> --agent</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> pi</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> --target</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> .</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> --yes</span></span></code></pre></div><p>The script runs the catalogued <code>npx -y skills@1.7.4 add</code> commands with explicit agent selection. It acquires required legal files before starting installations, verifies skill metadata and prerequisites, and removes catalogued unwanted metadata such as <code>agents/openai.yaml</code>. It never executes installed helpers or initializers.</p><p>Normal installations keep a verified canonical folder at <code>.agents/skills/&lt;name&gt;</code> under the project, or under your home for personal scope. Selected Claude destinations and personal OpenCode config destinations use exact relative symlink projections to that folder. Native Skills CLI 1.7.4 writes Pi/OpenCode assets to the canonical directory, but Claude writes its own directory. The wrapper verifies those actual native outputs before normalizing the final layout; it does not mistake an older canonical copy for fresh Claude output.</p><p>The CLI verifies selected destinations and rejects unsafe symlink traversal. A successful run lists verified skills. It does not modify <code>AGENTS.md</code>, referenced instruction documents, personal command registration, or legacy manager locks.</p><p>For normal agent installations, the external Skills CLI owns its own installation records. Custom-directory acquisition records exist only in the disposable workspace. There is no new custom manager-owned lock, persistent apply-plan ID, or staging protocol.</p><h2 id="relative-markdown-links" tabindex="-1">Relative Markdown links <a class="header-anchor" href="#relative-markdown-links" aria-label="Permalink to &quot;Relative Markdown links&quot;">​</a></h2><p>Source skills use category directories, but installed skills use flat names. Sync rebases Markdown links, images, and reference definitions against the original source paths and final installed layout. A reference to a declared dependency resolves against that dependency&#39;s catalogued source and installed location.</p><p>Operational skill references in portable packages may target only self and declared required skills. Skill overview READMEs describe intent, real dependencies, and verified factual origin or inspiration. They may include short usage examples and standalone install instructions using the pinned acquisition tool, without depending on the sync CLI. Attribution does not add an installation dependency. Verification rejects operational undeclared references, optional or reverse recommendations, collection/sync-tool guidance, and overview content outside that contract rather than adding dependencies to justify them. Same-skill links remain unchanged. Source-attribution and technical-reference links can use source-ref GitHub URLs, with raw file URLs for fallback images. Queries and fragments are preserved. The link routine does not add dependencies or install referenced skills.</p><p>Only destination URLs change. Prose, labels, frontmatter, code examples, and required legal files stay unchanged. This parser-based routine does not repair already-invalid source links or raw HTML attributes. It runs on freshly acquired files before custom output is published; it needs no LLM. Normal installs can still have partial writes if later verification fails.</p><h2 id="update-selected-skills" tabindex="-1">Update selected skills <a class="header-anchor" href="#update-selected-skills" aria-label="Permalink to &quot;Update selected skills&quot;">​</a></h2><p>Existing selected destinations block installation by default, including unmanaged or locally edited copies. Inspect them first. Pass <code>--overwrite</code> only if you approve replacing the displayed selected skills, then preview again before confirming. Unselected/custom skill directories remain outside the operation.</p><p>A destination without its own <code>SKILL.md</code> that contains child skill folders is a collection, not one installed skill. The CLI refuses to replace it, even with <code>--overwrite</code>. Choose a separate destination project or output directory to preserve the authored sources.</p><p>A failed command or verification stops subsequent installations. Already completed writes are not rolled back automatically. The error names the stopped skill and completed skills. Inspect partial output before retrying; do not delete legacy locks or bypass conflicts to make a retry pass.</p><h2 id="unsupported-semantic-adaptations" tabindex="-1">Unsupported semantic adaptations <a class="header-anchor" href="#unsupported-semantic-adaptations" aria-label="Permalink to &quot;Unsupported semantic adaptations&quot;">​</a></h2><p>The current catalog contains no unprepared remote adaptations. <code>code-review</code>, <code>tdd</code>, and <code>wait-what</code> have reviewed local variants, with pinned upstream provenance and original/project licenses. Their portable instructions are committed source files, not generated during synchronization. <code>wait-what</code> prefers the project glossary and includes a generic fallback in its own folder. <code>grill-me</code> and <code>writing-for-agents</code> use unchanged pinned upstream instructions, with required supporting files. The upstream <code>grill-me</code> body calls the Skill tool for <code>grilling</code>; the catalog keeps <code>grilling</code> in its installation closure but does not add a project-specific <code>requires</code> field or rewrite the upstream call. A compatible skill-invocation mechanism is needed, and live harness invocation remains unverified. The script filters <code>agents/openai.yaml</code>; it does not remove unrelated OpenAPI documents.</p><p>Sync needs no LLM or model API credentials. It copies prepared content, includes declared skill prerequisites, preserves required support/legal files, and applies deterministic exclusions. Review and publish source upgrades separately; a future remote entry that still needs semantic changes remains blocked until a maintained variant is available. Do not disable that guard or relabel unreviewed content just to make installation succeed. Missing runtime tools are reported as requirements, not installed by this script.</p><p>For a reviewed CLI commit or tag, pass the same value through <code>--ref</code> to select that revision&#39;s authored and maintained skill files. This is required for newly published source paths that are not yet on the catalog&#39;s default <code>main</code> ref. It also makes repeated runs select the same maintained source bytes.</p><h2 id="install-an-individual-skill-directly" tabindex="-1">Install an individual skill directly <a class="header-anchor" href="#install-an-individual-skill-directly" aria-label="Permalink to &quot;Install an individual skill directly&quot;">​</a></h2><p>After reviewing its source, you can use the external Skills CLI without the wrapper. For example:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">npx</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -y</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> skills@1.7.4</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> add</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> https://github.com/dragoscirjan/ai/tree/main/.agents/skills/utility/isolated-workspace</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> --skill</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> isolated-workspace</span></span></code></pre></div><p>This acquires only the named skill. Raw Skills CLI commands do not automatically install the project&#39;s declared instruction requirements or apply its catalog filtering and legal-file rules. Missing required skills stop invocation until you explicitly arrange their setup. <a href="/projects/ai-skills/skills/">Find a skill</a> and check its requirements first.</p><h2 id="review-agents-md-and-its-dependencies" tabindex="-1">Review AGENTS.md and its dependencies <a class="header-anchor" href="#review-agents-md-and-its-dependencies" aria-label="Permalink to &quot;Review AGENTS.md and its dependencies&quot;">​</a></h2><p>Install the separate user-invoked skill only when wanted:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-light-font-style:italic;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">npx</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> -y</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> skills@1.7.4</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> add</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> https://github.com/dragoscirjan/ai/tree/main/.agents/skills/agentic-work/sync-my-agents</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> --skill</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> sync-my-agents</span></span></code></pre></div><p>Use a published ref containing that skill. The command above installs into the project. The wrapper also includes <code>sync-my-agents</code> in the Agentic work checklist by default. To install personally, use explicit <code>--skill sync-my-agents --scope personal --agent pi</code> with the wrapper, or add <code>--global</code> to the direct command. Personal scope is never inferred from a category selection. Installing the skill does not invoke it, run setup, or authorize instruction edits.</p><p>Invoke <code>sync-my-agents</code> and identify the project and requested instruction work. It follows relevant document references, inspects evidence, clarifies material unknowns, and presents exact diffs. Approve those diffs separately before editing. It preserves existing policy and custom instructions and does not impose a template bundle.</p><p>Dependencies here mean instruction documents, not skill installation prerequisites. Missing required skills stop the affected phase; <code>sync-my-agents</code> never installs them. A review that finds no necessary change leaves documents untouched.</p><h2 id="migrate-from-the-combined-manager" tabindex="-1">Migrate from the combined manager <a class="header-anchor" href="#migrate-from-the-combined-manager" aria-label="Permalink to &quot;Migrate from the combined manager&quot;">​</a></h2><p>The source <code>sync-my-skills</code> skill, custom engine, command stubs, and manager-specific schemas are retired. Existing installations, command registrations, and <code>.agents/ai-assets.lock.json</code> files in other projects remain unchanged. Review any exact removal separately under that project&#39;s safeguards. Do not invoke the retired command expecting it to run this CLI.</p><p>Instruction templates remain reusable assets, but they are not a mandatory instruction bundle for the new skill. Merging, publishing, tool setup, trust changes, and initializers remain separate permissions.</p>`,57)])])}const u=i(n,[["render",l]]);export{k as __pageData,u as default};
